// Read-only gate replay; velocities are reconstructed from recorded poses, not a new estimator run.
#include "bhu/external_nav.hpp"
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>
using Row=std::map<std::string,double>;
std::vector<Row> read(const std::string& path){std::ifstream f(path);if(!f)throw std::runtime_error(path);std::string s,k;std::getline(f,s);std::stringstream hs(s);std::vector<std::string> keys;while(std::getline(hs,k,','))keys.push_back(k);std::vector<Row> rows;while(std::getline(f,s)){std::stringstream ls(s);std::vector<double> v;while(std::getline(ls,k,','))v.push_back(std::stod(k));if(v.size()!=keys.size())continue;Row r;for(size_t i=0;i<v.size();++i)r[keys[i]]=v[i];rows.push_back(r);}return rows;}
int main(int argc,char**argv)try{if(argc!=3)throw std::runtime_error("replay_arducopter_gate TRACKING.csv RECOVERY_COMPARISON.csv");auto tracking=read(argv[1]),poses=read(argv[2]);std::map<uint64_t,Row> byCapture;for(auto&r:tracking)byCapture[r.at("host_capture_us")]=r;bhu::extnav::DurationGate direct(0,0,0,0);Eigen::Vector3d previous=Eigen::Vector3d::Zero();double previousTime=0;uint64_t count=0,passed=0,late=0,oldPassed=0;const double begin=poses.back().at("gate_now_us")-300e6;for(auto&r:poses){auto it=byCapture.find(r.at("host_capture_us"));if(it==byCapture.end())continue;auto&t=it->second;bhu::extnav::Sample s;s.capture_host_us=r.at("host_capture_us");s.reset_epoch=r.at("epoch");s.imu_initialized=t.at("initialized");s.imu_healthy=t.at("imu_healthy");s.frame_alignment_valid=s.imu_initialized;s.quality=t.at("quality");s.tracking_ok=!t.at("support_reject_mask");s.T_W_C.translation()<<r.at("x"),r.at("y"),r.at("z");s.T_W_C.linear()=Eigen::Quaterniond(r.at("qw"),r.at("qx"),r.at("qy"),r.at("qz")).toRotationMatrix();const auto time=t.at("device_s");if(s.imu_initialized){if(previousTime>0&&time>previousTime){s.camera_velocity_W=(s.T_W_C.translation()-previous)/(time-previousTime);s.velocity_valid=s.camera_velocity_W.norm()<10;}previous=s.T_W_C.translation();previousTime=time;}else previousTime=0;auto now=uint64_t(r.at("gate_now_us"));auto accepted=direct.accept(s,now);if(r.at("gate_now_us")>=begin){++count;passed+=bool(accepted);oldPassed+=r.at("baseline_eligible")!=0;late+=accepted&&now-s.capture_host_us>150000;}}std::cout<<"{\"frames\":"<<count<<",\"old_baseline_eligible\":"<<oldPassed<<",\"direct_eligible\":"<<passed<<",\"direct_eligible_older_than_150ms\":"<<late<<",\"method\":\"C++ gate replay with reconstructed pose-difference velocity; angular velocity unavailable and zero; no EKF or accuracy validation\"}\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
